from pathlib import Path
p=Path('sv-website-5.html')
s=p.read_text(encoding='utf-8')
s=s.replace("var effectSafetyGuard = {active:false,observer:null,header:null,footer:null,main:null,nodes:[]};","var effectSafetyGuard = {active:false,observer:null,header:null,footer:null,main:null,nodes:[],headerChildren:[],footerChildren:[]};",1)
s=s.replace("effectSafetyGuard.main=document.getElementById('main');effectSafetyGuard.nodes=[];[effectSafetyGuard.header,effectSafetyGuard.main,effectSafetyGuard.footer].forEach(function(root){","effectSafetyGuard.main=document.getElementById('main');effectSafetyGuard.nodes=[];effectSafetyGuard.headerChildren=effectSafetyGuard.header?Array.prototype.slice.call(effectSafetyGuard.header.childNodes):[];effectSafetyGuard.footerChildren=effectSafetyGuard.footer?Array.prototype.slice.call(effectSafetyGuard.footer.childNodes):[];[effectSafetyGuard.header,effectSafetyGuard.main,effectSafetyGuard.footer].forEach(function(root){",1)
s=s.replace("function restoreEffectSafetyBaseline(){if(!effectSafetyGuard.active)return;effectSafetyGuard.nodes.forEach(restoreEffectSafetyNode);","function restoreEffectSafetyChildren(root,children){if(!root||!children||!children.length||!document.documentElement.contains(root))return;var same=root.childNodes.length===children.length;for(var i=0;same&&i<children.length;i++){if(root.childNodes[i]!==children[i])same=false;}if(!same){while(root.firstChild)root.removeChild(root.firstChild);children.forEach(function(node){root.appendChild(node);});}}\n  function restoreEffectSafetyBaseline(){if(!effectSafetyGuard.active)return;effectSafetyGuard.nodes.forEach(restoreEffectSafetyNode);restoreEffectSafetyChildren(effectSafetyGuard.header,effectSafetyGuard.headerChildren);restoreEffectSafetyChildren(effectSafetyGuard.footer,effectSafetyGuard.footerChildren);",1)
